  ?><!doctype html><html><head><meta charset="utf-8"><title>Teacher Evaluation Analytics</title><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="assests/css/dashboard.css"></head><body><?php include '../../includes/admin_sidebar.php';?><main class="main-content"><?php include '../../includes/admin_header.php';?><div style="padding:28px"><h1>Teacher Evaluation Analytics</h1><p style="color:#6b7280">Select an evaluation campaign.</p><?php foreach($list as $x):?><div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;margin:12px 0"><strong><?=htmlspecialchars($x['title'])?></strong><div><?=htmlspecialchars($x['label'])?> · <?=htmlspecialchars($x['status'])?> · <?=htmlspecialchars($x['start_date'])?> → <?=htmlspecialchars($x['end_date'])?></div><a href="evaluation_analytics.php?evaluation_id=<?=(int)$x['evaluation_id']?>">View Analytics</a></div><?php endforeach;?></div></main></body></html><?php exit;
