 requireAdminModule('analytics','read');
$evaluationId=(int)($_GET['evaluation_id']??0);$e=$pdo->prepare("SELECT te.*,sy.label FROM teacher_evaluations te JOIN schoolyears sy ON sy.school_year_id=te.school_year_id WHERE te.evaluation_id=?");$e->execute([$evaluationId]);$evaluation=$e->fetch(PDO::FETCH_ASSOC);if(!$evaluation)exit('Evaluation not found.');
$stats=$pdo->prepare("SELECT t.teacher_id,t.firstname,t.lastname,sub.subject_name,COUNT(DISTINCT er.response_id) responses,ROUND(AVG(ea.rating),2) average FROM evaluation_responses er JOIN classofferings co ON co.offering_id=er.offering_id JOIN teachers t ON t.teacher_id=co.teacher_id JOIN subjects sub ON sub.subject_id=co.subject_id JOIN evaluation_answers ea ON ea.response_id=er.response_id JOIN evaluation_questions eq ON eq.question_id=ea.question_id AND eq.question_type='rating' WHERE er.evaluation_id=? GROUP BY t.teacher_id,sub.subject_id ORDER BY t.lastname,t.firstname,sub.subject_name");$stats->execute([$evaluationId]);$rows=$stats->fetchAll(PDO::FETCH_ASSOC);
$cat=$pdo->prepare("SELECT t.teacher_id,t.firstname,t.lastname,eq.category,ROUND(AVG(ea.rating),2) average,COUNT(ea.answer_id) answers FROM evaluation_responses er JOIN classofferings co ON co.offering_id=er.offering_id JOIN teachers t ON t.teacher_id=co.teacher_id JOIN evaluation_answers ea ON ea.response_id=er.response_id JOIN evaluation_questions eq ON eq.question_id=ea.question_id WHERE er.evaluation_id=? AND eq.question_type='rating' GROUP BY t.teacher_id,eq.category ORDER BY t.lastname,t.firstname,eq.sort_order");$cat->execute([$evaluationId]);$categories=$cat->fetchAll(PDO::FETCH_ASSOC);
$comments=$pdo->prepare("SELECT t.teacher_id,t.firstname,t.lastname,ea.text_answer FROM evaluation_responses er JOIN classofferings co ON co.offering_id=er.offering_id JOIN teachers t ON t.teacher_id=co.teacher_id JOIN evaluation_answers ea ON ea.response_id=er.response_id JOIN evaluation_questions eq ON eq.question_id=ea.question_id WHERE er.evaluation_id=? AND eq.question_type='text' AND ea.text_answer<>'' ORDER BY er.submitted_at DESC");$comments->execute([$evaluationId]);$comments=$comments->fetchAll(PDO::FETCH_ASSOC);
$summaryStmt=$pdo->prepare("SELECT * FROM evaluation_ai_summaries WHERE evaluation_id=?");$summaryStmt->execute([$evaluationId]);$summaries=[];foreach($summaryStmt->fetchAll(PDO::FETCH_ASSOC) as $s)$summaries[$s['teacher_id']]=$s;
function esc($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
