<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teacher Evaluation Analytics</title><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="assests/css/dashboard.css"><style>.wrap{padding:28px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:22px;margin-bottom:18px}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #eee;text-align:left}.muted{color:#6b7280}.summary{background:#f8fafc;border-radius:10px;padding:14px;margin-top:10px}.comment{padding:8px 0;border-bottom:1px solid #eee}</style></head><body><?php include '../../includes/admin_sidebar.php';?><main class="main-content"><?php include '../../includes/admin_header.php';?><div class="wrap"><a href="teacher_evaluation.php">← Teacher Evaluation</a><h1><?=esc($evaluation['title'])?></h1><p class="muted"><?=esc($evaluation['label'])?> · <?=esc($evaluation['status'])?> · <?=esc($evaluation['start_date'])?> → <?=esc($evaluation['end_date'])?></p>
<div class="card"><h2>Overview</h2><p>Responses: <strong><?=count(array_unique(array_column($rows,'responses')))?></strong> teacher/class result rows. Numerical scores below are calculated directly from survey answers; Gemini only summarizes the feedback.</p></div>
<div class="card"><h2>Teacher Results</h2><table><tr><th>Teacher</th><th>Subject</th><th>Responses</th><th>Average</th></tr><?php foreach($rows as $r):?><tr><td><?=esc($r['firstname'].' '.$r['lastname'])?></td><td><?=esc($r['subject_name'])?></td><td><?=$r['responses']?></td><td><?=$r['average']?> / 5</td></tr><?php endforeach;?></table></div>
<div class="card"><h2>Category Results</h2><table><tr><th>Teacher</th><th>Category</th><th>Average</th><th>Answers</th></tr><?php foreach($categories as $r):?><tr><td><?=esc($r['firstname'].' '.$r['lastname'])?></td><td><?=esc($r['category'])?></td><td><?=$r['average']?> / 5</td><td><?=$r['answers']?></td></tr><?php endforeach;?></table></div>
<div class="card"><h2>Written Feedback</h2><?php if(!$comments):?><p class="muted">No written feedback yet.</p><?php else:foreach($comments as $c):?><div class="comment"><strong><?=esc($c['firstname'].' '.$c['lastname'])?></strong>: <?=esc($c['text_answer'])?></div><?php endforeach;endif;?></div>
<div class="card"><h2>Gemini Summary</h2><p class="muted">Generate summaries from aggregated scores and written comments. Student names/IDs are never sent to Gemini.</p><form method="post" action="generate_evaluation_ai.php"><input type="hidden" name="csrf" value="<?=htmlspecialchars(generateCSRFToken())?>"><input type="hidden" name="evaluation_id" value="<?=$evaluationId?>"><button class="btn primary" type="submit">Generate / Refresh Gemini Summaries</button></form><?php foreach($summaries as $s):?><div class="summary"><h3><?=esc($s['teacher_id'])?></h3><p><?=nl2br(esc($s['summary_text']))?></p><small>Generated <?=esc($s['generated_at'])?> using <?=esc($s['model'])?></small></div><?php endforeach;?></div>
</div></main></body></html>